#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>
#include <string>
#include <vector>
#include <cstring>
#include <mutex>
#include <unordered_map>
#include <chrono>
#include <memory>

namespace cloud_sdk {
namespace auth {

struct ServiceCredential {
    std::string service_id;
    std::string region;
    unsigned char master_key[32];
    uint64_t key_epoch;
};

class NonceDerivationContext {
public:
    NonceDerivationContext(const std::string& scope) : scope_(scope) {
        rotation_counter_ = 0;
    }

    void advance() { rotation_counter_++; }
    uint64_t counter() const { return rotation_counter_; }
    const std::string& scope() const { return scope_; }

private:
    std::string scope_;
    uint64_t rotation_counter_;
};

class DerivedKeyCache {
public:
    struct CacheEntry {
        unsigned char derived_key[32];
        unsigned char base_iv[12];
        uint64_t uses;
        uint64_t max_uses;
    };

    bool lookup(const std::string& key_id, CacheEntry& out) {
        std::lock_guard<std::mutex> lock(mu_);
        auto it = cache_.find(key_id);
        if (it != cache_.end()) {
            memcpy(&out, &it->second, sizeof(CacheEntry));
            return true;
        }
        return false;
    }

    void store(const std::string& key_id, const CacheEntry& entry) {
        std::lock_guard<std::mutex> lock(mu_);
        cache_[key_id] = entry;
    }

    void increment_use(const std::string& key_id) {
        std::lock_guard<std::mutex> lock(mu_);
        auto it = cache_.find(key_id);
        if (it != cache_.end()) {
            it->second.uses++;
        }
    }

private:
    std::mutex mu_;
    std::unordered_map<std::string, CacheEntry> cache_;
};

class CrossServiceAuthenticator {
public:
    CrossServiceAuthenticator(const ServiceCredential& cred)
        : cred_(cred), nonce_ctx_("cross-service-auth") {
        key_cache_ = std::make_shared<DerivedKeyCache>();
    }

    // Derives a per-target encryption IV using HKDF-like construction
    // The IV incorporates the nonce context counter to prevent reuse
    std::vector<unsigned char> derive_iv_for_target(
            const std::string& target_service,
            const NonceDerivationContext& ctx) {
        unsigned char iv[12];
        // Derive IV from master key + target + counter
        unsigned char hmac_out[32];
        unsigned int hmac_len = 0;

        std::string label = target_service + ":" + ctx.scope() + ":" +
                           std::to_string(ctx.counter());

        HMAC(EVP_sha256(), cred_.master_key, 32,
             (unsigned char*)label.c_str(), label.size(),
             hmac_out, &hmac_len);

        // Truncate HMAC output to 12 bytes for GCM IV
        memcpy(iv, hmac_out, 12);

        return std::vector<unsigned char>(iv, iv + 12);
    }

    // Generate authentication token for cross-service call
    std::vector<unsigned char> generate_auth_token(
            const std::string& target_service,
            const std::string& payload) {

        std::string cache_key = cred_.service_id + ":" + target_service +
                               ":" + std::to_string(cred_.key_epoch);

        DerivedKeyCache::CacheEntry entry;
        if (!key_cache_->lookup(cache_key, entry)) {
            // Derive a new key for this service pair
            derive_service_key(target_service, entry);
            entry.uses = 0;
            entry.max_uses = 1ULL << 32;
            key_cache_->store(cache_key, entry);
        }

        // Compute IV: XOR base_iv with usage counter
        unsigned char effective_iv[12];
        compute_effective_iv(entry.base_iv, entry.uses, effective_iv);

        key_cache_->increment_use(cache_key);

        // Encrypt payload with AES-256-GCM
        std::vector<unsigned char> ciphertext(payload.size() + 16);
        int outlen = 0;
        int tmplen = 0;

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, nullptr, nullptr);
        EVP_EncryptInit_ex(ctx, nullptr, nullptr, entry.derived_key, effective_iv);

        // AAD: service identifiers
        std::string aad = cred_.service_id + ":" + target_service;
        EVP_EncryptUpdate(ctx, nullptr, &outlen,
                         (unsigned char*)aad.c_str(), aad.size());

        EVP_EncryptUpdate(ctx, ciphertext.data(), &outlen,
                         (unsigned char*)payload.c_str(), payload.size());
        int ct_len = outlen;

        EVP_EncryptFinal_ex(ctx, ciphertext.data() + ct_len, &tmplen);
        ct_len += tmplen;

        // Append GCM tag
        unsigned char tag[16];
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
        memcpy(ciphertext.data() + ct_len, tag, 16);

        EVP_CIPHER_CTX_free(ctx);
        ciphertext.resize(ct_len + 16);

        return ciphertext;
    }

private:
    void derive_service_key(const std::string& target,
                           DerivedKeyCache::CacheEntry& entry) {
        std::string info = "service-key:" + cred_.service_id + ":" + target;
        unsigned char prk[32];
        unsigned int prk_len;

        HMAC(EVP_sha256(), cred_.master_key, 32,
             (unsigned char*)info.c_str(), info.size(),
             prk, &prk_len);
        memcpy(entry.derived_key, prk, 32);

        // Derive base IV from the same PRK
        std::string iv_info = "iv:" + info;
        unsigned char iv_material[32];
        unsigned int iv_len;
        HMAC(EVP_sha256(), prk, 32,
             (unsigned char*)iv_info.c_str(), iv_info.size(),
             iv_material, &iv_len);
        memcpy(entry.base_iv, iv_material, 12);
    }

    void compute_effective_iv(const unsigned char* base_iv,
                             uint64_t counter,
                             unsigned char* out) {
        memcpy(out, base_iv, 12);
        // XOR counter into the last 8 bytes of IV
        // BUG: We read entry.uses BEFORE increment_use is called,
        // but due to the cache lookup returning a COPY, the uses
        // field is stale. Multiple concurrent calls get the same
        // counter value, causing IV reuse with the same key.
        uint64_t ctr_be = __builtin_bswap64(counter);
        for (int i = 0; i < 8; i++) {
            out[4 + i] ^= ((unsigned char*)&ctr_be)[i];
        }
    }

    ServiceCredential cred_;
    NonceDerivationContext nonce_ctx_;
    std::shared_ptr<DerivedKeyCache> key_cache_;
};

} // namespace auth
} // namespace cloud_sdk
